<script setup lang="ts">
import { computed, ref } from 'vue'
import { Search, UserFilled } from '@element-plus/icons-vue'
import { appState } from '../data/repository'
import { currency } from '../utils'
const keyword=ref(''),segment=ref('全部分群'),drawer=ref(false),selected=ref(appState.customers[0])
const rows=computed(()=>appState.customers.filter(x=>(!keyword.value||x.name.includes(keyword.value)||x.email.includes(keyword.value))&&(segment.value==='全部分群'||x.segment===segment.value)))
function open(row:typeof appState.customers[number]){selected.value=row;drawer.value=true}
</script>
<template><section data-testid="customers-page"><div class="customer-summary"><div><el-icon><UserFilled/></el-icon><span>會員總數<strong>{{appState.customers.length}}</strong></span></div><div><span>活躍會員<strong>{{appState.customers.filter(x=>x.status==='active').length}}</strong></span></div><div><span>高價值會員<strong>{{appState.customers.filter(x=>x.segment==='高價值').length}}</strong></span></div><div><span>會員總產值<strong>{{currency(appState.customers.reduce((s,x)=>s+x.spent,0))}}</strong></span></div></div><article class="table-panel"><div class="filters"><el-input v-model="keyword" :prefix-icon="Search" placeholder="搜尋姓名或電子郵件"/><el-select v-model="segment"><el-option v-for="x in ['全部分群','一般','活躍','高價值','沉睡']" :key="x" :value="x" :label="x"/></el-select></div><el-table :data="rows" @row-click="open"><el-table-column label="會員" min-width="220"><template #default="{row}"><div class="member"><span>{{row.name.slice(0,1)}}</span><div><strong>{{row.name}}</strong><small>{{row.email}}</small></div></div></template></el-table-column><el-table-column label="分群" width="110"><template #default="{row}"><el-tag round effect="plain">{{row.segment}}</el-tag></template></el-table-column><el-table-column prop="orders" label="訂單數" width="100"/><el-table-column label="累積消費" width="140"><template #default="{row}"><strong>{{currency(row.spent)}}</strong></template></el-table-column><el-table-column prop="joinedAt" label="加入日期" width="120"/><el-table-column label="狀態" width="90"><template #default="{row}"><span :class="['dot',row.status]"></span>{{row.status==='active'?'正常':'停用'}}</template></el-table-column></el-table></article><el-drawer v-model="drawer" title="會員詳細" size="420px"><div class="drawer-profile"><span>{{selected.name.slice(0,1)}}</span><h2>{{selected.name}}</h2><p>{{selected.email}}</p><el-tag>{{selected.segment}}</el-tag></div><div class="drawer-metrics"><div><span>累積消費</span><strong>{{currency(selected.spent)}}</strong></div><div><span>完成訂單</span><strong>{{selected.orders}}</strong></div></div><el-divider/><h3>會員資訊</h3><dl><dt>會員編號</dt><dd>{{selected.id}}</dd><dt>加入日期</dt><dd>{{selected.joinedAt}}</dd><dt>會員狀態</dt><dd>{{selected.status==='active'?'正常':'停用'}}</dd></dl></el-drawer></section></template>
<style scoped>.customer-summary{display:grid;grid-template-columns:repeat(4,1fr);background:#173425;border-radius:16px;color:white;margin-bottom:18px}.customer-summary>div{padding:20px 24px;border-right:1px solid #ffffff17;display:flex;align-items:center;gap:12px}.customer-summary>div:last-child{border:0}.customer-summary span{display:grid;font-size:11px;color:#9eb4a5;gap:5px}.customer-summary strong{font-size:21px;color:white}.table-panel{background:white;border:1px solid #e3e8e3;border-radius:16px;overflow:hidden}.filters{display:grid;grid-template-columns:1fr 160px;gap:10px;padding:18px;border-bottom:1px solid #edf0ec}.member{display:flex;align-items:center;gap:10px}.member>span{display:grid;place-items:center;width:36px;height:36px;border-radius:12px;background:#e2ece5;color:#306548;font-weight:800}.member div{display:grid}.member small{font-size:10px;color:#8f9891}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:7px}.dot.active{background:#3a9a65}.dot.inactive{background:#aaa}.drawer-profile{text-align:center}.drawer-profile>span{display:grid;place-items:center;width:72px;height:72px;border-radius:24px;background:#dcebe1;color:#2d6748;font-size:25px;font-weight:900;margin:auto}.drawer-profile h2{margin:14px 0 3px}.drawer-profile p{color:#879189;margin:0 0 10px}.drawer-metrics{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:25px}.drawer-metrics div{display:grid;padding:15px;background:#f3f6f3;border-radius:12px}.drawer-metrics span{font-size:11px;color:#8b958e}.drawer-metrics strong{font-size:19px;margin-top:5px}.el-drawer dl{display:grid;grid-template-columns:1fr 1fr;gap:14px;font-size:13px}.el-drawer dt{color:#8b958e}.el-drawer dd{text-align:right;margin:0}@media(max-width:800px){.customer-summary{grid-template-columns:repeat(2,1fr)}.filters{grid-template-columns:1fr}}</style>
